/**
 * Machine SM Agent — GitHub-issues machine-loop watchdog (JSRunner).
 *
 * The dark-factory loop over GitHub issues (dev → PR → CI → rework → AI
 * review → merge → close) relies on `labeled` events to wake the
 * ai-teammate workflow. Labels added with the workflow's own GITHUB_TOKEN
 * do NOT fire `labeled` events (GitHub rule), so every machine-added
 * label — agent:rework after red CI, pr_approved after an APPROVE verdict
 * — is a dead letter unless a human re-arms it (issue #116). This agent
 * is the safety net: a deterministic reconciler (no AI CLI, no LLM) that
 * runs on a short cron tick, reads the ACTUAL state of every
 * machine-managed issue (labels, linked PR, check rollup, merge state,
 * active workflow runs) and performs whatever step the state calls for —
 * dispatching legs directly via workflow_dispatch (GITHUB_TOKEN CAN
 * dispatch; only label events are mute), updating branches, merging
 * approved PRs, closing issues whose PRs merged.
 *
 * Concurrency contract: if any AI Teammate run is queued/in_progress the
 * agent idles for the whole tick (the cron re-fires soon — short ticks,
 * no long sleeps), so parallel runs finish before new legs start and the
 * per-issue concurrency group in ai-teammate.yml never cancels mid-flight
 * work. `maxConcurrentRuns` (default 1) relaxes this when the machine can
 * afford parallel legs.
 *
 * Configuration (override priority, sm-style):
 *   1. jobParams in agents/machine_sm.json (defaults)
 *   2. .dmtools/config.js `machineSm` section (project override)
 *      { machineSm: { dryRun: true, maxConcurrentRuns: 1, ... } }
 *   3. CLI JSON override (outer `params` wrapper — same quirk as sm):
 *      dmtools run agents/machine_sm.json '{"params":{"jobParams":{"dryRun":true}}}'
 *
 * jobParams fields:
 *   dryRun            — log the plan, perform no action (default false)
 *   maxConcurrentRuns — idle unless active AI Teammate runs < this (default 1)
 *   maxReworkRounds   — mirrors ai-teammate.yml MAX_AUTO_REWORK_ROUNDS (default 2)
 *   workflowFile      — the machine workflow to dispatch (default ai-teammate.yml)
 *   branchPrefix      — machine dev-branch prefix (default 'ai/gh-')
 *   agentHandle       — assignee that marks an issue machine-managed (default 'ai-teammate')
 *   issueLimit        — how many open issues to scan per tick (default 50)
 *   closeComment      — comment posted by the close-issue safety net
 *
 * Decision core (decideActions) is pure and unit-tested; all GitHub I/O
 * goes through `gh` via cli_execute_command and is injectable/mocks-able
 * through jobParams.ghRunner for tests.
 */
'use strict';

var configLoader = require('./configLoader.js');

// ─────────────────────────────────────────────────────────────────────────────
// Pure decision core — decideActions(state, cfg) → actions[]
//
// state = {
//   issue:  { number, labels: [..], assignees: [..] },
//   pr:     null | { number, state: 'OPEN'|'MERGED'|'CLOSED',
//                    checkConclusion: 'red'|'green'|'pending'|'none',
//                    mergeState: 'CLEAN'|'BEHIND'|'DIRTY'|'BLOCKED'|'UNKNOWN',
//                    mergeable: bool|null },
//   activeRunForIssue: bool
// }
// cfg = { maxReworkRounds: int }
// ─────────────────────────────────────────────────────────────────────────────
function decideActions(state, cfg) {
    var actions = [];
    var labels = (state.issue && state.issue.labels) || [];
    var has = function (l) { return labels.indexOf(l) !== -1; };
    var maxRounds = (cfg && cfg.maxReworkRounds) || 2;

    // 'blocked' = human hold (fa #939): the official freeze switch — the
    // reconciler skips the item ENTIRELY (no dead-letter re-fire, no branch
    // update, no merge, no close) until a human removes the label.
    // Engine-level, evaluated before every other decision; the SM rule
    // engine (githubSource.matchesGuards) honors the same label.
    if (has('blocked')) {
        actions.push({ type: 'skip', reason: 'blocked — human hold; the machine skips this item entirely' });
        return actions;
    }
    if (has('needs-human')) {
        actions.push({ type: 'skip', reason: 'needs-human — waiting for a human' });
        return actions;
    }
    if (state.activeRunForIssue) {
        actions.push({ type: 'skip', reason: 'active AI Teammate run for this issue' });
        return actions;
    }

    // Rework round cap — mirrors ai-teammate.yml MAX_AUTO_REWORK_ROUNDS:
    // escalate instead of looping rework forever.
    var rounds = 0;
    labels.forEach(function (l) {
        var m = /^rework-round-(\d+)$/.exec(l);
        if (m) rounds = Math.max(rounds, parseInt(m[1], 10));
    });
    var reworkExhausted = rounds >= maxRounds;

    var pr = state.pr;
    if (!pr) {
        // No open PR and nothing merged for this issue yet.
        if (has('ai_developed')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'ai_developed but no open PR (dead dev run)' });
        } else if (has('agent:dev')) {
            actions.push({ type: 'dispatch', leg: 'dev',
                reason: 'agent:dev labeled, no PR yet (dead dev letter)' });
        } else if (has('agent:rework')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'stale agent:rework with no PR' });
        } else {
            actions.push({ type: 'skip', reason: 'no PR and no machine leg to (re)fire' });
        }
        return actions;
    }

    if (pr.state !== 'OPEN') {
        if (pr.state === 'MERGED') {
            actions.push({ type: 'closeIssue',
                reason: 'linked PR #' + pr.number + ' merged (Fixes #N safety net)' });
        } else {
            actions.push({ type: 'skip', reason: 'linked PR #' + pr.number + ' is ' + pr.state });
        }
        return actions;
    }

    if (pr.checkConclusion === 'pending') {
        actions.push({ type: 'skip', reason: 'PR #' + pr.number + ' checks pending' });
        return actions;
    }

    if (pr.checkConclusion === 'red') {
        if (reworkExhausted) {
            actions.push({ type: 'label', label: 'needs-human',
                reason: 'CI red after ' + rounds + ' rework rounds — escalating' });
        } else {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'CI red on PR #' + pr.number + (has('agent:rework')
                    ? ' (stale agent:rework — dead letter re-fire)'
                    : '') });
        }
        return actions;
    }

    // ── green below ──────────────────────────────────────────────────────────
    if (has('pr_approved')) {
        if (pr.mergeState === 'BEHIND') {
            actions.push({ type: 'updateBranch',
                reason: 'approved but behind main — updating branch' });
        } else if (pr.mergeState === 'CLEAN' || pr.mergeable === true) {
            actions.push({ type: 'merge',
                reason: 'approved + green + mergeable (merge-trigger parity)' });
        } else {
            actions.push({ type: 'skip',
                reason: 'approved but merge state ' + pr.mergeState });
        }
        return actions;
    }

    if (has('ai_developed') && !has('ai_pr_reviewed')) {
        actions.push({ type: 'dispatch', leg: 'review',
            reason: 'green PR #' + pr.number + ' awaits machine review' });
        return actions;
    }
    if (has('ai_pr_reviewed') && !has('pr_approved')) {
        // Reviewed but the verdict never reached approve. The review leg
        // itself labels agent:rework for CHANGES_REQUESTED verdicts; if
        // that label is present with no active run it is another dead
        // letter — re-fire it. Otherwise wait (verdict processing pending).
        if (has('agent:rework')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'stale agent:rework after review (dead letter re-fire)' });
        } else {
            actions.push({ type: 'skip',
                reason: 'reviewed, verdict not approve — awaiting rework labeling' });
        }
        return actions;
    }

    actions.push({ type: 'skip', reason: 'steady state' });
    return actions;
}

// ────────────────────…

/**
 * mergeBot — event-driven fast path for the machine loop's merge stage.
 *
 * The SM tick (cron every-10-minutes) is best-effort: GitHub silently drops scheduled
 * runs under load (live: fa ticks vanished for 30+ min while approved
 * green PRs waited). This bot runs on EVENTS — CI conclusion
 * (workflow_run), label changes / head pushes (pull_request), check-run
 * completions, and manual dispatch — and performs exactly the
 * deterministic, idempotent stage transitions that need no orchestration:
 *
 *   approved + ai_validating + green + CLEAN  -> squash-merge (retry once
 *                                                on transient API errors)
 *   ai_validating + green + CLEAN + !approved-> latch ai_validated, unarm
 *   ai_validating + green + base moved       -> unarm (stale head; the SM
 *                                                refreshes + re-validates)
 *
 * Everything else (validation dispatch, review/rework legs, conflict
 * rework, fail-validation reporting) stays SM-owned: the bot never
 * dispatches workflows, never arms labels beyond the two latches above —
 * it only CONCLUDES stages whose evidence is already on the PR.
 *
 * One exception (owner rule 2026-10-04): a deferred approved PR with
 * acted==0 at end-of-run fires a single machine-sm.yml tick (self-heal,
 * 'gh workflow run machine-sm.yml -F dryRun=false --repo owner/name'),
 * skipped when a machine-sm.yml run is already active — see the
 * END-OF-RUN SELF-TICK block in action() and hasActiveSmRun().
 *
 * jsrunner contract: repo comes from params.jobParams.repo
 * ("owner/name") or GH_REPO; tools are the global snake_case bridge.
 */

/* global github_list_prs, github_get_pr, github_get_commit_check_runs,
   github_list_workflow_runs, github_merge_pr, github_add_labels,
   github_remove_label, cli_execute_command */

function parseMcp(raw) {
    if (raw === null || raw === undefined) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(String(raw)); } catch (e) { return {}; }
}

function labelNames(pr) {
    return (pr.labels || []).map(function (l) { return (l && l.name) || l; });
}

/**
 * Epoch ms when the run started waiting (check-run started_at, workflow-run
 * created_at) or null when the payload carries no usable timestamp — the
 * gh-766 stale-head detection FAILS OPEN on null (treated as live).
 */
function pendingStartedAt(r) {
    if (!r) return null;
    var raw = r.started_at || r.startedAt || r.created_at || r.createdAt;
    if (!raw) return null;
    var ts = Date.parse(raw);
    return isNaN(ts) ? null : ts;
}

/**
 * Same rollup as checksRollup, plus pendingSince: the OLDEST start time
 * among the pending evidence (gh-766) — an armed head whose checks have
 * been motionless past staleHeadMinutes is a dead FIFO head (skipped with
 * an explicit log line, unarmed, queue advances) instead of an eternal
 * 'checks=pending — waiting'.
 */
function rollupDetail(commitSha, pr, job, owner, name) {
    var cr = parseMcp(github_get_commit_check_runs({
        workspace: owner, repository: name, commitSha: commitSha
    }));
    var runs = cr.check_runs || cr.total_count !== undefined ? (cr.check_runs || []) : [];
    if (!runs.length && pr && Array.isArray(pr.statusCheckRollup) && pr.statusCheckRollup.length) {
        runs = pr.statusCheckRollup;
    }
    if (!runs.length) {
        // Workflow-run fallback (live: fa #762): the REST PR body has NO
        // statusCheckRollup (GraphQL-only) and API silent-updated heads carry
        // no check runs — but the SM-dispatched CI run IS on this exact sha.
        // Read the repo's CI workflow runs and match head_sha. The SM's own
        // waiter is a pull_request-event job: it never re-runs on refreshed
        // heads, so this is the ONLY conclusive evidence for them.
        var wf = parseMcp(github_list_workflow_runs({
            workspace: owner, repository: name,
            workflowId: (job && job.ciWorkflow) || 'ci.yml', perPage: 30
        }));
        var wruns = (wf && (wf.workflow_runs || wf.runs)) || [];
        var mine = wruns.filter(function (r) { return String(r.head_sha || r.headSha) === String(commitSha); });
        if (mine.length) {
            // newest first (API order); conclusion decides, in-flight waits
            var top = mine[0];
            var c = top.conclusion ? String(top.conclusion).toUpperCase() : null;
            if (c === 'SUCCESS') return { state: 'green', pendingSince: null };
            if (c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED') return { state: 'red', pendingSince: null };
            return { state: 'pending', pendingSince: pendingStartedAt(top) };
        }
        return { state: 'none', pendingSince: null };
    }
    if (!runs.length) return { state: 'none', pendingSince: null };
    var red = false, pending = false, oldestPending = null;
    runs.forEach(function (r) {
        var c = r.conclusion ? String(r.conclusion).toUpperCase() : null;
        var s = r.status ? String(r.status).toUpperCase() : null;
        if (c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED') red = true;
        else if (!c || s === 'QUEUED' || s === 'IN_PROGRESS' || s === 'WAITING' || s === 'PENDING') {
            pending = true;
            var st = pendingStartedAt(r);
            if (st !== null && (oldestPending === null || st < oldestPending)) oldestPending = st;
        }
    });
    if (red) return { state: 'red', pendingSince: null };
    if (pending) return { state: 'pending', pendingSince: oldestPending };
    return { state: 'green', pendingSince: null };
}

/**
 * Check-rollup for a head sha: 'green' (all concluded SUCCESS), 'red'
 * (any FAILURE/TIMED_OUT/CANCELLED), 'pending' (queued/in flight),
 * 'none' (no evidence at all — nothing concluded anywhere).
 *
 * Fallback (live: fa #762, 2026-09-22): silent-update refreshes a branch
 * via the update-branch API, which fires NO pull_request event — the
 * gate waiter check run never re-runs on the new head, so commit check
 * runs come back EMPTY even though the dispatched CI (check suites) is
 * green on that exact sha. When check runs are empty, fall back to the
 * PR-level statusCheckRollup (suites + statuses aggregated by GitHub)
 * before declaring 'none' — otherwise a green approved CLEAN head waits
 * forever and only the SM tick's better-informed merge can land it.
 */
function checksRollup(commitSha, pr, job, owner, name) {
    return rollupDetail(commitSha, pr, job, owner, name).state;
}

/**
 * mergeState, deterministic (smProvider.prStatus parity, minimal): REST
 * mergeable_state mapped to UPPER, DIRTY on mergeable===false, BEHIND when
 * the base moved (base.sha vs the live base branch head via github_list_prs
 * is unavailable — use mergeable_state 'behind' plus the base sha vs
 * github_get_pr(base).head? The PR body carries base.sha only). For the
 * bot's decisions BEHIND matters only to NOT merge a stale head — REST
 * already reports 'behind' for those; keep BLOCKED (checks pending under
 * protection) and CLEAN as REST says, DIRTY/BEHIND/other as REST says.
 */
function mergeStateOf(pr) {
    if (pr.mergeable === false) return 'DIRTY';
    var ms = pr.mergeStateStatus ||
        (pr.mergeable_state ? String(pr.mergeable_state).toUpperCase() : '');
    return ms || (pr.mergeable === true ? 'CLEAN' : 'UNKNOWN');
}

/**
 * SM-active probe (review #701, tick-storm fix): TRUE when a machine-sm.yml
 * run is queued/in_progress/waiting/pending — the SM is already about to
 * drain the queue itself, so the end-of-run self-tick must NOT stack another
 * one. Mirrors smAgent's hasActiveTargetWorkflowRun semantics: a queued run
 * older than 6h is a zombie (the concurrency group superseded it) and does
 * not count. The workflow-id form of the listing 404s for some PATs (live fa
 * 2026-09-23, same fallback as smAgent's validation-sync) — fall back to the
 * all-runs endpoint and filter by workflow path client-side. An unlistable
 * repo fails OPEN (dispatch anyway): a missed tick stalls the conveyor, a
 * duplicate one is idempotent.
 */
function hasActiveSmRun(owner, name) {
    var runs = [];
    try {
        var wf = pars…

/**
 * Machine-author resolution for the #687 PR lifecycle.
 *
 * Whose login counts as "the machine" (the identities the harness authors
 * PRs through) is deployment-specific — this repo never hardcodes it. The
 * knob is a comma-separated LIST of logins since gh-728 (owner directive
 * 2026-10-05: 'ai-teammate,github-actions[bot]' — the CI bot opens its own
 * PRs, live fa PR #1249): `resolveMachineAuthor` returns the raw string;
 * `machineAuthorLogins` splits it; `isMachineAuthored` (authors) and
 * `isMachineLogin` (commit actors) match any entry. All machine-keyed
 * guards (the `notMachine` review rule, the rework re-arm in PR-anchored
 * reviews, the SM `prMachineAuthor` query gate, the sticky-park RESET)
 * resolve through these helpers. Resolution order:
 *
 *   1. `jobParams.machineAuthor` — the JSON parameter at factory setup:
 *      factory-sm.yml `machine-author` input lands in the `dmtools run`
 *      override (`{"params":{"jobParams":{...,"machineAuthor":"..."}}}}`).
 *      The global-level knob: set once by the harness (machine-sm.yml),
 *      valid for every repo the factory runs against.
 *   2. `config.machineAuthor` — the per-repo `.dmtools/config.js` knob,
 *      for fleets where different repos run different bots.
 *   3. `null` — no machine author configured. Every guard keyed on it is
