                requestedSide = (lineInfo.side === 'LEFT' && submoduleHasNewPointer(diffText, effectivePath))
                    ? 'RIGHT'
                    : (lineInfo.side || 'RIGHT');
                if (submodulePath !== filePath || inlineComment.line != 1) {
