        var mod = loadModule(MOD, makeRequire({ './reviewVerdicts.js': rvReal() }, {}), {});
        var threw = false;
        try {
            mod.createSmProvider({ scm: { provider: 'bitbucket' },
                repository: { owner: 'a', repo: 'b' } });
