        assert.equal(threw, true);
    });

    test('missing repository is rejected loudly', function () {
        var mod = loadModule(MOD, makeRequire({ './reviewVerdicts.js': rvReal() }, {}), {});
        var threw = false;
        try { mod.createSmProvider({ scm: { provider: 'github' } }); }
        catch (e) { threw = true; }
