    var text = String(body || '');
    if (!text) return 'none';
    if (SEVERITY_BLOCKING_RE.test(text)) return 'blocking';
    if (SEVERITY_IMPORTANT_RE.test(text)) return 'important';
    if (SEVERITY_SUGGESTION_RE.test(text)) return 'suggestion';
    return 'none';
