        assert.equal(p.prStatus(7).checkConclusion, 'red');
        rollup = [{ status: 'IN_PROGRESS' }];
        assert.equal(p.prStatus(8).checkConclusion, 'pending');
        rollup = [{ conclusion: 'SUCCESS' }, { conclusion: 'SKIPPED' }];
