            github_get_pr_review_threads: function (args) {
                calls.push(args);
                return { data: { repository: { pullRequest: { reviewThreads: {
                    nodes: [
                        { id: 't1', isResolved: true, path: 'a.dart' },
                        { id: 't2', isResolved: true, path: 'b.dart' },
